export function twCss(value: string | undefined): string {
  if (!value) return "";
  const tokens = value.split(/\s+/);
  const utilities = tokens.flatMap((token) => (utilityMap[token] ?? "").split(/\s+/));
  return [...tokens, ...utilities].filter(Boolean).join(" ").trim();
}
